UPDATE runtime_operations SET progress_percent=?5,progress_stage=?6,updated_at=CAST(unixepoch('subsec') * 1000000 AS INTEGER) WHERE id=?1 AND attempt=?2 AND lease_token=?3 AND worker_id=?4 AND status='running' AND lease_expires_at>CAST(unixepoch('subsec') * 1000000 AS INTEGER) AND cancel_requested=0;